package com.ml.tblandroidtxt;
import org.json.JSONArray;import org.json.JSONObject;import java.util.List;
/** Two-call L2 runner. The RAW-only ledger must close before DRAFT is exposed. */
public final class EditorialL2Runner {
 public interface Client{OpenAICompatibleClient.ChatResult complete(AppSettings s,PromptPair p,String id)throws Exception;} public static final class Result{public final long runId;public final String output;Result(long id,String text){runId=id;output=text;}}
 private final EditorialRepository repo;private final Client client;public EditorialL2Runner(EditorialRepository r){this(r,(s,p,id)->OpenAICompatibleClient.chatWithUsage(s,p,s.maxOutputTokens,id));}EditorialL2Runner(EditorialRepository r,Client c){repo=r;client=c;}
 public Result run(long chapterId,AppSettings settings)throws Exception{EditorialRepository.Chapter chapter=repo.getChapter(chapterId);if(chapter==null)throw new IllegalArgumentException("Editorial chapter not found");if(chapter.state!=EditorialWorkflowV5.ChapterState.L1_CLOSED)throw new IllegalStateException("L2 requires a closed L1 machine gate");List<EditorialRepository.AssetSnapshot> assets=repo.chapterAssets(chapterId);String report=repo.latestEvidenceForChapter(chapterId,"REPORT_L1_JSON"),reportError=EditorialEvidenceValidator.validateL1Report(report);if(reportError!=null)throw new IllegalStateException("L2 blocked by REPORT_L1: "+reportError);PromptPair rawPrompt=EditorialL2ContextBuilder.rawMapping(chapterId,assets);if(!safe(rawPrompt)||totalChars(assets)+report.length()>EditorialL1ContextBuilder.MAX_INLINE_SOURCE_CHARS)return runSegmented(chapterId,settings,assets,report,false,-1);String manifest=manifest(chapterId,assets,report);long runId=repo.createRun(chapterId,"L2",settings.provider,settings.model,HashUtil.sha256(rawPrompt.system+"\n"+rawPrompt.user),HashUtil.sha256(EditorialEvidenceSchema.VERSION),manifest);repo.saveEvidence(runId,"L2_CONTEXT_MANIFEST",manifest);repo.updateRunState(runId,"RAW_MAPPING");repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L1_CLOSED,EditorialWorkflowV5.ChapterState.L2_READY);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L2_READY,EditorialWorkflowV5.ChapterState.L2_RAW_MAPPING);EditorialWorkflowV5.ChapterState active=EditorialWorkflowV5.ChapterState.L2_RAW_MAPPING;
  try{OpenAICompatibleClient.ChatResult raw=client.complete(settings,rawPrompt,"editorial-l2:"+runId+":raw-ledger");String error=EditorialL2RawLedgerContract.validate(raw.content,String.valueOf(chapterId));if(error!=null)throw new IllegalArgumentException("L2 RAW ledger contract failed: "+error);repo.saveEvidence(runId,"L2_RAW_LEDGER",raw.content);repo.saveEvidence(runId,"L2_RAW_LEDGER_USAGE",usage(raw));repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L2_RAW_MAPPING,EditorialWorkflowV5.ChapterState.L2_RUNNING);active=EditorialWorkflowV5.ChapterState.L2_RUNNING;repo.updateRunState(runId,"RUNNING");PromptPair editPrompt=EditorialL2ContextBuilder.edit(chapterId,assets,raw.content,report);requireSafeContext(editPrompt,"edit");OpenAICompatibleClient.ChatResult edit=client.complete(settings,editPrompt,"editorial-l2:"+runId+":edit");error=EditorialEvidenceValidator.validateL2Output(edit.content);if(error!=null)throw new IllegalArgumentException("L2 output contract failed: "+error);JSONObject root=new JSONObject(edit.content);if(!String.valueOf(chapterId).equals(root.optString("chapterId")))throw new IllegalArgumentException("L2 output chapterId does not match run");persistGates(runId,root.getJSONObject("gates"));repo.saveEvidence(runId,"GLOBAL_CHANGE_REGISTER",root.getJSONArray("globalChanges").toString());repo.saveEvidence(runId,"VI_L2_JSON",edit.content);repo.saveEvidence(runId,"VI_L2_TEXT",root.getString("output"));repo.saveEvidence(runId,"L2_EDIT_USAGE",usage(edit));repo.updateRunState(runId,"CLOSED");repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L2_RUNNING,EditorialWorkflowV5.ChapterState.L2_CLOSED);return new Result(runId,root.getString("output"));}
  catch(Exception e){repo.saveEvidence(runId,"L2_FAILURE",new JSONObject().put("phase",active.name()).put("message",String.valueOf(e.getMessage())).toString());repo.updateRunState(runId,"FAILED");repo.transitionChapter(chapterId,active,EditorialWorkflowV5.ChapterState.FAILED);throw e;}}
 public Result retry(long chapterId,AppSettings settings)throws Exception{EditorialRepository.Chapter c=repo.getChapter(chapterId);if(c==null||c.state!=EditorialWorkflowV5.ChapterState.FAILED)throw new IllegalStateException("No failed L2 checkpoint to retry");long runId=repo.latestRunId(chapterId,"L2");if(runId<=0)throw new IllegalStateException("Failed L2 run not found");List<EditorialRepository.AssetSnapshot> assets=repo.chapterAssets(chapterId);String report=repo.latestEvidenceForChapter(chapterId,"REPORT_L1_JSON");repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.FAILED,EditorialWorkflowV5.ChapterState.L2_READY);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L2_READY,EditorialWorkflowV5.ChapterState.L2_RAW_MAPPING);repo.updateRunState(runId,"RAW_MAPPING");return runSegmented(chapterId,settings,assets,report,true,runId);}
 private Result runSegmented(long chapterId,AppSettings settings,List<EditorialRepository.AssetSnapshot> assets,String report,boolean reuse,long existingRun)throws Exception{EditorialSceneSegmenter.Plan plan=EditorialL1ContextBuilder.segmentRawForL1(assets);String manifest=manifest(chapterId,assets,report);long runId=existingRun>0?existingRun:repo.createRun(chapterId,"L2",settings.provider,settings.model,HashUtil.sha256(EditorialL2SceneContract.schema()),HashUtil.sha256(EditorialEvidenceSchema.VERSION),manifest);if(!reuse){repo.saveEvidence(runId,"L2_CONTEXT_MANIFEST",manifest);repo.updateRunState(runId,"RAW_MAPPING");repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L1_CLOSED,EditorialWorkflowV5.ChapterState.L2_READY);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L2_READY,EditorialWorkflowV5.ChapterState.L2_RAW_MAPPING);}EditorialRepository.AssetSnapshot g=find(assets,EditorialWorkflowV5.AssetRole.GLOSSARY),p=find(assets,EditorialWorkflowV5.AssetRole.PRONOUN),draft=find(assets,EditorialWorkflowV5.AssetRole.DRAFT);EditorialWorkflowV5.ChapterState active=EditorialWorkflowV5.ChapterState.L2_RAW_MAPPING;String activeScene="raw";
  try{JSONArray ledgerScenes=new JSONArray();for(EditorialSceneSegmenter.Scene scene:plan.scenes){activeScene="raw:"+scene.id;String type="L2_RAW_SCENE_"+scene.id,payload=reuse?repo.evidencePayload(runId,type):"";OpenAICompatibleClient.ChatResult response=null;if(EditorialL2RawLedgerContract.validate(payload,String.valueOf(chapterId))!=null){PromptPair prompt=EditorialL2ContextBuilder.rawScene(chapterId,scene,g.content,p.content);requireSafeContext(prompt,"RAW scene");response=client.complete(settings,prompt,"editorial-l2:"+runId+":raw:"+scene.id);payload=response.content;}JSONObject root=new JSONObject(payload);String error=EditorialL2RawLedgerContract.validate(payload,String.valueOf(chapterId));if(error!=null)throw new IllegalArgumentException("L2 RAW scene contract failed: "+error);JSONArray rows=root.getJSONArray("scenes");if(rows.length()!=1)throw new IllegalArgumentException("RAW checkpoint must contain exactly one scene");JSONObject row=rows.getJSONObject(0);if(!scene.id.equals(row.optString("id"))||!scene.startAnchor.equals(row.optString("rawStart"))||!scene.endAnchor.equals(row.optString("rawEnd")))throw new IllegalArgumentException("RAW ledger anchors mismatch at "+scene.id);ledgerScenes.put(row);repo.saveScene(runId,"l2-raw-"+scene.id,scene.startAnchor,scene.endAnchor,"CLOSED",row.toString());if(response!=null){repo.saveEvidence(runId,type,payload);repo.saveEvidence(runId,type+"_USAGE",usage(response));}}
   JSONObject ledger=new JSONObject().put("chapterId",String.valueOf(chapterId)).put("scenes",ledgerScenes);String ledgerError=EditorialL2RawLedgerContract.validate(ledger.toString(),String.valueOf(chapterId));if(ledgerError!=null)throw new IllegalStateException(ledgerError);repo.saveEvidence(runId,"L2_RAW_LEDGER",ledger.toString());repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L2_RAW_MAPPING,EditorialWorkflowV5.ChapterState.L2_RUNNING);active=EditorialWorkflowV5.ChapterState.L2_RUNNING;repo.updateRunState(runId,"RUNNING");List<EditorialDraftSceneMapper.Pair> pairs=resolvePairs(chapterId,plan,assets);if(pairs.size()!=plan.scenes.size())throw new IllegalStateException("L2 scene mapping count mismatch");StringBuilder output=new StringBuilder();JSONArray changes=new JSONArray();for(int i=0;i<pairs.size();i++){EditorialDraftSceneMapper.Pair pair=pairs.get(i);EditorialSceneSegmenter.Scene scene=plan.scenes.get(i);activeScene="edit:"+scene.id;String type="L2_EDIT_SCENE_"+scene.id,payload=reuse?repo.evidencePayload(runId,type):"";OpenAICompatibleClient.ChatResult response=null;if(EditorialL2SceneContract.validate(payload)!=null){PromptPair prompt=EditorialL2ContextBuilder.editScene(chapterId,scene.id,scene.startAnchor,scene.endAnchor,scene.raw,pair.draft,ledgerScenes.getJSONObject(i).toString(),reportForScene(report,scene),g.content,p.content);requireSafeContext(prompt,"edit scene");response=client.complete(settings,prompt,"editorial-l2:"+runId+":edit:"+scene.id);payload=response.content;}JSONObject row=new JSONObject(payload);String error=EditorialL2SceneContract.validate(payload);if(error!=null)throw new IllegalArgumentException("L2 edit scene contract failed: "+error);if(!scene.id.equals(row.optString("sceneId"))||!scene.startAnchor.equals(row.optString("rawStart"))||!scene.endAnchor.equals(row.optString("rawEnd")))throw new IllegalArgumentException("L2 edit anchors mismatch at "+scene.id);output.append(row.getString("output"));JSONArray local=row.getJSONArray("changes");for(int x=0;x<local.length();x++)changes.put(local.getJSONObject(x));repo.saveScene(runId,"l2-edit-"+scene.id,scene.startAnchor,scene.endAnchor,"CLOSED",row.toString());if(response!=null){repo.saveEvidence(runId,type,payload);repo.saveEvidence(runId,type+"_USAGE",usage(response));}}
   JSONObject gates=closedGates(),root=new JSONObject().put("schema",EditorialEvidenceSchema.VERSION).put("run","L2").put("chapterId",String.valueOf(chapterId)).put("output",output.toString()).put("outputComplete",true).put("globalChanges",changes).put("gates",gates);String error=EditorialEvidenceValidator.validateL2Output(root.toString());if(error!=null)throw new IllegalStateException("Aggregated L2 contract failed: "+error);persistGates(runId,gates);repo.saveEvidence(runId,"GLOBAL_CHANGE_REGISTER",changes.toString());repo.saveEvidence(runId,"VI_L2_JSON",root.toString());repo.saveEvidence(runId,"VI_L2_TEXT",output.toString());repo.updateRunState(runId,"CLOSED");repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L2_RUNNING,EditorialWorkflowV5.ChapterState.L2_CLOSED);return new Result(runId,output.toString());
  }catch(Exception e){repo.saveEvidence(runId,"L2_FAILURE",new JSONObject().put("phase",active.name()).put("scene",activeScene).put("message",String.valueOf(e.getMessage())).toString());repo.updateRunState(runId,"FAILED");repo.transitionChapter(chapterId,active,EditorialWorkflowV5.ChapterState.FAILED);throw e;}}
 private List<EditorialDraftSceneMapper.Pair> resolvePairs(long chapterId,EditorialSceneSegmenter.Plan plan,List<EditorialRepository.AssetSnapshot> assets)throws Exception{List<EditorialDraftSceneMapper.Pair> pairs=EditorialL1ContextBuilder.mapDraftForL1(assets);boolean aligned=pairs.size()==plan.scenes.size();for(EditorialDraftSceneMapper.Pair x:pairs)aligned&=x.status==EditorialDraftSceneMapper.Status.ALIGNED;if(aligned)return pairs;String evidence=repo.latestEvidenceForChapter(chapterId,"L1_MODEL_MAPPING");if(evidence.trim().isEmpty())throw new IllegalStateException("Validated L1 model mapping evidence is required for segmented L2");return EditorialModelSceneMapper.fromEvidence(plan,find(assets,EditorialWorkflowV5.AssetRole.DRAFT).content,evidence);}
 private static String reportForScene(String report,EditorialSceneSegmenter.Scene scene)throws Exception{JSONObject source=new JSONObject(report),out=new JSONObject().put("chapterId",source.optString("chapterId"));JSONArray scenes=new JSONArray();for(int i=0;i<source.getJSONArray("scenes").length();i++){JSONObject x=source.getJSONArray("scenes").getJSONObject(i);if(scene.id.equals(x.optString("id")))scenes.put(x);}JSONArray issues=new JSONArray();for(int i=0;i<source.getJSONArray("issues").length();i++){JSONObject x=source.getJSONArray("issues").getJSONObject(i);String anchor=x.optString("rawAnchor");if(anchor.compareTo(scene.startAnchor)>=0&&anchor.compareTo(scene.endAnchor)<=0)issues.put(x);}return out.put("scenes",scenes).put("issues",issues).toString();}
 private static JSONObject closedGates()throws Exception{return new JSONObject().put("coverage","CLOSED").put("fidelity","CLOSED").put("referenceVoice","CLOSED").put("continuityStructure","CLOSED").put("change","CLOSED");}private static EditorialRepository.AssetSnapshot find(List<EditorialRepository.AssetSnapshot> a,EditorialWorkflowV5.AssetRole role){for(EditorialRepository.AssetSnapshot x:a)if(x.role==role)return x;throw new IllegalArgumentException("Missing "+role);}
 private void persistGates(long id,JSONObject g){save(id,EditorialWorkflowV5.Gate.COVERAGE,g,"coverage");save(id,EditorialWorkflowV5.Gate.FIDELITY,g,"fidelity");save(id,EditorialWorkflowV5.Gate.REFERENCE_VOICE,g,"referenceVoice");save(id,EditorialWorkflowV5.Gate.CONTINUITY_STRUCTURE,g,"continuityStructure");save(id,EditorialWorkflowV5.Gate.CHANGE,g,"change");}private void save(long id,EditorialWorkflowV5.Gate gate,JSONObject g,String key){repo.saveGate(id,gate,EditorialWorkflowV5.GateStatus.valueOf(g.optString(key)),g.toString());}
 private static int totalChars(List<EditorialRepository.AssetSnapshot> assets){int n=0;for(EditorialRepository.AssetSnapshot a:assets)n+=a.content.length();return n;}private static boolean safe(PromptPair p){return p.system.length()+p.user.length()<=EditorialL1ContextBuilder.MAX_INLINE_SOURCE_CHARS;}private static void requireSafeContext(PromptPair p,String phase){if(!safe(p))throw new IllegalStateException("L2 "+phase+" exceeds safe context; smaller segmentation is required");}private static String manifest(long id,List<EditorialRepository.AssetSnapshot> assets,String report)throws Exception{JSONArray rows=new JSONArray();for(EditorialRepository.AssetSnapshot a:assets)rows.put(new JSONObject().put("role",a.role.name()).put("sha256",a.sha256));return new JSONObject().put("chapterId",String.valueOf(id)).put("rawFirst",true).put("assets",rows).put("reportL1Hash",HashUtil.sha256(report)).toString();}private static String usage(OpenAICompatibleClient.ChatResult r)throws Exception{return new JSONObject().put("promptTokens",r.promptTokens).put("completionTokens",r.completionTokens).put("totalTokens",r.totalTokens).put("finishReason",r.finishReason).put("responseId",r.providerResponseId).toString();}
}
